-- WhatsNew.lua: generated from CHANGELOG.md by the release (make_whatsnew.py; do not edit by hand).
-- Per version: v, date, items = { { s = "add"|"chg"|"fix", fr = { title, text }, en = { title, text } } }
local _, ns = ...
ns.WHATSNEW = {
  { v = "1.0.0-beta.216", date = "2026-11-23", items = {
    { s = "fix", fr = { "Sacs dit quand LibForeverData est désactivé.", "Sans cette bibliothèque, la fenêtre ne sait pas quelle quête utilise quel objet : elle ne liste plus rien et dit de l'activer dans la liste des addons, au lieu de proposer des objets au hasard." }, en = { "The Bags window says when LibForeverData is turned off instead of listing items it cannot judge.", "" } },
    { s = "fix", fr = { "Omokk's Head et Warosh's Scroll sont reliés à la quête Urok Doomhowl", ". Une fois la quête rendue, Sacs les propose." }, en = { "Omokk's Head and Warosh's Scroll are tied to \"Urok Doomhowl\": offered once it is turned in.", "" } },
  } },
  { v = "1.0.0-beta.215", date = "2026-11-23", items = {
    { s = "fix", fr = { "Sacs ne propose plus de jeter un objet qu'aucune quête connue n'utilise.", "La liste « À détruire toi-même » mettait des objets que nos données ne savent pas relier à une quête : le Unadorned Seal of Ascension (la clé du pic Rochenoire supérieur), Omokk's Head et Warosh's Scroll (Urok Doomhowl), les Deadwood Tribal Beads (monnaie des furbolgs Barkskin). Ne pas les connaître ne veut pas dire qu'ils sont inutiles : ils ne sont plus listés. Seuls restent les objets d'une quête rendue, et ceux d'une quête d'une autre faction ou classe." }, en = { "The Bags window no longer lists items no known quest uses (the Upper Blackrock Spire seal, Omokk's Head, Warosh's Scroll, the Barkskin beads): unknown is not useless.", "" } },
  } },
  { v = "1.0.0-beta.214", date = "2026-11-23", items = {
    { s = "chg", fr = { "Les objectifs de farm vont sur la zone bleue du jeu, avec un point fixe.", "Le guide ne calcule plus ses propres zones de farm : elles ne collaient pas aux zones bleues de la carte et leur point te suivait à chaque pas. Le GPS va maintenant sur la zone de quête du jeu (la zone bleue), sinon sur le point de l'objectif dans nos données, et ce point ne bouge plus pendant que tu farmes. Les contours en pointillés et l'étiquette « Dans la zone » sont retirés." }, en = { "Farm objectives use the game's blue quest area as one fixed point, as other guides do: our own outlines and the spot that followed you are gone.", "" } },
  } },
  { v = "1.0.0-beta.213", date = "2026-11-23", items = {
    { s = "fix", fr = { "Plus de repère toutes les secondes dans une zone de farm.", "Dans la zone, le point du guide suit tes pas : WL Helper redemandait un repère à Naowh Forever à chaque mouvement (« Waypoint for Unseen Servant » en boucle dans le chat) et le GPS le suivait comme un repère posé par toi. Le repère reste maintenant en place tant que tu restes à moins de 60 m, et le GPS ne le prend plus pour le tien." }, en = { "No more waypoint every second in a farm area", "The guide's map pin stays put while its spot moves less than 60 yards, and a pin placed through Naowh Forever is no longer followed as a \"Map pin\"." } },
  } },
  { v = "1.0.0-beta.212", date = "2026-11-23", items = {
    { s = "chg", fr = { "Unstable Magic se prend et se rend toute seule.", "La quête répétable des Mote of Unstable Magic (Nuara Tremorhoof pour la Horde, Archmage Celindra pour l'Alliance) est prise, rendue et reprise sans un clic, même si son guide n'est pas coché. Parle au PNJ avec tes Motes dans les sacs : ça tourne tant que tu en as assez. Ce sont les mêmes réglages que les quêtes du guide (Réglages > Quêtes et donjons > Quêtes du guide) ; garde Maj enfoncée pour le faire à la main." }, en = { "Unstable Magic (Mote of Unstable Magic) is taken and handed in by itself, again and again while you have the motes, with the guide quests' switches; hold Shift to do it by hand.", "" } },
  } },
  { v = "1.0.0-beta.211", date = "2026-11-23", items = {
    { s = "fix", fr = { "T0.5 du mage : la dernière quête dit quoi apporter.", "Saving the Best for Last demande la Magister's Crown et les Magister's Robes (vérifié sur Wowhead WoW Forever). Les deux sont liées au ramassage : la couronne tombe sur Darkmaster Gandling à Scholomance (environ 12 %), la robe sur General Drakkisath au pic Rochenoire supérieur (environ 10 %). Le guide te dit de les garder de n'importe quel passage." }, en = { "Mage Dungeon Set 2", "Saving the Best for Last now lists Magister's Crown (Darkmaster Gandling) and Magister's Robes (General Drakkisath), both bind on pickup." } },
    { s = "fix", fr = { "Rapport de mémoire plus juste.", "À côté du temps le plus lent, il donne maintenant la moyenne : une seule ouverture de carte lente, comme la première après un écran de chargement, ne fait plus croire que la carte est lente." }, en = { "Memory report", "The average time is shown beside the slowest one." } },
  } },
  { v = "1.0.0-beta.210", date = "2026-11-23", items = {
    { s = "fix", fr = { "La flèche ne vise plus un point quand tu es déjà au milieu des monstres.", "Les échantillons de venin de Silithus (T0.5, An Earnest Proposition) se farment maintenant sur une zone de six camps de scorpides, et non plus sur un seul point. Dans un camp, la flèche te dit « Dans la zone » ; ailleurs, elle t'envoie au camp le plus proche. Même chose pour quelques autres quêtes de farm : les chauves-souris et les chiens de la peste des Maleterres de l'Est, les Swamp Talkers du marais des Chagrins, les Azsharite Formations d'Azshara et les yétis d'Hivernale." }, en = { "Farming objectives", "Silithus Venom Samples and a few other kill or loot quests now use a zone of camps; in a camp the arrow says \"In the area\" instead of pointing at one spot." } },
  } },
  { v = "1.0.0-beta.209", date = "2026-11-23", items = {
    { s = "fix", fr = { "Flèche du guide coupée : plus de flèche « Repère sur la carte » qui revient quand même.", "Quand tu coupes la flèche du guide, il pose à la place le repère de carte du jeu. WL Helper le prenait pour un repère posé par toi et relançait une flèche dessus. Le guide ne fait donc plus réapparaître de flèche une fois que tu l'as coupée." }, en = { "Guide arrow switched off", "The guide's own map pin no longer starts a \"Map pin\" arrow." } },
  } },
  { v = "1.0.0-beta.208", date = "2026-11-23", items = {
    { s = "fix", fr = { "T0.5 du mage : la ceinture et les gants s'achètent aussi.", "Just Compensation demande les Magister's Belt et Magister's Gloves. Comme les Bindings, ils sont liés quand équipés (vérifié sur Wowhead WoW Forever) : le guide te dit de les acheter à l'hôtel des ventes, ou de garder ceux d'un passage au pic Rochenoire ou à Scholomance, au lieu de t'envoyer dans un donjon pour eux." }, en = { "Mage Dungeon Set 2", "Just Compensation's Magister's Belt and Gloves are bind-on-equip (checked on Wowhead WoW Forever): buy them or keep them from a run, no dungeon run for them." } },
  } },
  { v = "1.0.0-beta.207", date = "2026-11-23", items = {
    { s = "fix", fr = { "Set de donjon 2 (T0.5) : plus de Stratholme dès le départ.", "An Earnest Proposition demande une pièce du set de donjon 1, par exemple les Magister's Bindings pour un mage. Les données ne savaient pas où la trouver, alors le guide te faisait faire tout Stratholme avant même de rendre la quête. Cette pièce est liée quand équipée et tombe au pic Rochenoire : le guide te dit maintenant de l'acheter à l'hôtel des ventes ou de garder celle d'un passage au pic. La route commence par les échantillons, puis Mokvar." }, en = { "Dungeon Set 2", "An Earnest Proposition's Dungeon Set 1 piece is bind-on-equip (buy it or keep one from Blackrock Spire): the route no longer starts with a full Stratholme run." } },
    { s = "fix", fr = { "Quêtes renumérotées par Forever : les compteurs sont lus sous le bon numéro.", "Une quête que Forever a renumérotée, comme An Earnest Proposition (84157), voyait ses objectifs lus sous notre ancien numéro. Le jeu répondait alors n'importe quoi, et une étape passait pour faite alors que tu n'avais rien fait (les échantillons de Silithus, par exemple)." }, en = { "Renumbered quests", "Objectives are now read under the quest log's own number, so a step is no longer skipped as done." } },
    { s = "fix", fr = { "Corrigé grâce à vos relevés en jeu", "Le chef de guerre Goretooth, à Kargath, est en 3.1, 47.7 et non en 5.8, 47.4 ; Unstable Magic donne 14 550 XP, pas 8 300 ; la dernière quête de Scooty à Baie-du-Butin ne demande plus Rig Wars ; les deux Allegiance to the Old Gods ne demandent plus Trouble in the Deeps." }, en = { "From the guild's in-game quest records", "Goretooth's position, Unstable Magic's XP, and three prerequisites the game does not need; checked on Wowhead WoW Forever." } },
    { s = "fix", fr = { "Relevés de quêtes plus justes.", "Un prérequis n'est plus noté « pas nécessaire » quand c'est celui de l'autre faction, quand tu l'as rendu sous un numéro propre à Forever, ou quand il est encore dans ton journal." }, en = { "Quest records", "A faction twin, a renumbered quest or one still in the log is no longer noted as \"not a prerequisite\"." } },
    { s = "fix", fr = { "La sauvegarde ne grossit plus sans fin.", "Les rapports déjà livrés partent après 14 jours, ceux qui n'ont jamais trouvé de destinataire après 45 jours, et ceux reçus dans une boîte de réception après 60 jours." }, en = { "Saved reports are pruned", "Delivered ones after 14 days, undelivered after 45, received ones after 60." } },
  } },
  { v = "1.0.0-beta.206", date = "2026-11-22", items = {
    { s = "fix", fr = { "Messages entre addons : un seul débit, celui du serveur.", "Tous les échanges de WL Helper (rapports, synchronisation de groupe, guilde, clés, événements, bateaux, version...) passent maintenant par une seule file. Chaque type de message part 10 fois d'affilée au plus, puis une fois par seconde, et le tout reste sous 800 octets par seconde, comme les bibliothèques d'addons connues. Avant, un long rapport ou une synchronisation partaient plus vite que ce que le serveur accepte, et les morceaux en trop étaient perdus sans un mot. Un message que le jeu refuse parce qu'il va trop vite repart un peu plus tard." }, en = { "Addon messages", "Every WL Helper exchange now goes through one queue paced to the server's limits (10 per prefix at once, then one a second, 800 bytes a second overall); throttled messages are sent again instead of being lost." } },
  } },
  { v = "1.0.0-beta.205", date = "2026-11-22", items = {
    { s = "fix", fr = { "Champs de bataille : plus d'erreur sur le bonus de la semaine", "Le calendrier du jeu peut cacher le type d'un événement (valeur protégée), et la fenêtre PvP plantait en le lisant. Le type caché compte maintenant comme inconnu, et c'est le titre de l'événement qui dit si c'est un bonus de champ de bataille." }, en = { "Battlegrounds", "No error when the calendar hides an event's type; the title decides." } },
  } },
  { v = "1.0.0-beta.204", date = "2026-11-22", items = {
    { s = "chg", fr = { "La chaîne du set de donjon 2 sort des trajets de donjon", "An Earnest Proposition ouvre une suite de classe d'une vingtaine de quêtes (Silithus, Stratholme, Blackrock Depths, puis l'amulette de Valthalak dans l'un des quatre donjons). Ce n'est pas une quête de donjon. Même commencée, elle ne remplit plus le trajet de LBRS ou d'un autre donjon : l'aperçu la montre verrouillée comme chaîne longue. Coche-la pour la suivre. Quand seule l'étape du donjon reste à faire, elle revient d'elle-même." }, en = { "The Dungeon Set 2 class chain stays out of dungeon routes, even started, unless ticked by hand or down to the dungeon's own step.", "" } },
  } },
  { v = "1.0.0-beta.203", date = "2026-11-22", items = {
    { s = "add", fr = { "Rapport automatique des quêtes renumérotées", "Quand le guide reconnaît par son titre une quête du journal dont le numéro nous est inconnu, il envoie tout seul un rapport discret à l'équipe WL Helper, une fois par numéro, pour qu'on l'ajoute aux données. An Earnest Proposition 84157 (vue chez un mage Horde) est déjà ajoutée." }, en = { "A renumbered quest recognised by its title is reported once, quietly, so its number goes into the data; An Earnest Proposition 84157 added.", "" } },
  } },
  { v = "1.0.0-beta.202", date = "2026-11-22", items = {
    { s = "fix", fr = { "Les quêtes que Forever a renumérotées", "Quelques quêtes connues ont un nouveau numéro sur Forever, par exemple An Earnest Proposition chez Mokvar (97411) ou les Just Compensation du set de donjon 2. Le guide ne les voyait pas dans ton journal et disait toujours « Accepter ». Maintenant, une quête du journal au numéro inconnu mais au titre connu compte pour la nôtre, si ton personnage peut la faire (faction, classe, race) : prise, prête à rendre, puis faite une fois rendue. Le nouveau numéro est retenu pour la suite de la chaîne." }, en = { "Quests Forever renumbered (An Earnest Proposition 97411, Just Compensation…) are recognised by their title, so the guide sees them taken, ready and turned in.", "" } },
  } },
}
